        <?php csrf_field(); ?><input type="hidden" name="action" value="recommend_budget"><input type="hidden" name="budget_month" value="<?= escape($budgetMonth) ?>"><input type="hidden" name="budget_version" value="<?= escape(budget_form_version($budget)) ?>"><input type="hidden" name="resources_version" value="<?= escape(budget_resources_version($budgetResources)) ?>">
