            <div><label for="cash-available">Monthly cash available · USD</label><input type="text" inputmode="decimal" id="cash-available" name="cash_available" maxlength="16" required placeholder="e.g. 2000" value="<?= escape(is_string($resourceValues['cash_available'] ?? null) ? $resourceValues['cash_available'] : ($budgetResources ? number_format($budgetResources['cash_cents'] / 100, 2, '.', '') : '')) ?>" aria-describedby="cash-help"></div>
            <div><label for="cash-reserve">Other savings or cushion (excluding Vacation Fund) · USD</label><input type="text" inputmode="decimal" id="cash-reserve" name="cash_reserve" maxlength="16" required value="<?= escape(is_string($resourceValues['cash_reserve'] ?? null) ? $resourceValues['cash_reserve'] : number_format(($budgetResources['reserve_cents'] ?? 0) / 100, 2, '.', '')) ?>"></div>
        </div>
        <p class="hint" id="cash-help">Use take-home pay after commitments paid outside these categories, such as rent, healthcare or debt payments. If an expense is already included in a category here, don’t subtract it again. This is a monthly plan; payday and bill timing still matter.</p>
        <?php if ($budgetResources && $budgetResources['month'] !== $budgetMonth): ?><p class="hint">Cash inputs carried forward from <?= escape(month_label($budgetResources['month'])) ?>. Update them if your situation changed.</p><?php endif; ?>
        <details class="recommendation-priorities"><summary>Priorities &amp; minimums <span class="muted">Choose where there’s room to cut</span></summary>
            <p class="hint">Essentials and mixed or unfamiliar categories start protected. “Protect” keeps the planning baseline unless you enter a minimum. Other categories can reduce toward zero or your chosen minimum. Spending already recorded this month is protected; Vacation Fund contributions are reserved separately before allocating expense targets. Change these choices to fit your needs.</p>
            <?php foreach ($budget['groups'] as $key => $group):
                $pref = $budgetResources['preferences'][$key] ?? ['priority' => budget_default_priority($group['name']), 'minimum_cents' => null];
