                $minimum = is_string($resourceValues['minimums'][$key] ?? null) ? $resourceValues['minimums'][$key] : ($pref['minimum_cents'] === null ? '' : number_format($pref['minimum_cents'] / 100, 2, '.', '')); ?>
            <div class="recommendation-priority-row"><strong><?= escape($group['name']) ?></strong>
                <div><label class="sr-only" for="priority-<?= escape($key) ?>"><?= escape($group['name']) ?> priority</label><select name="priorities[<?= escape($key) ?>]" id="priority-<?= escape($key) ?>"><?php foreach (['protect' => 'Protect', 'flexible' => 'Flexible', 'cut_first' => 'Cut first'] as $choice => $label): ?><option value="<?= $choice ?>" <?= $priority === $choice ? 'selected' : '' ?>><?= $label ?></option><?php endforeach; ?></select></div>
                <div><label class="sr-only" for="minimum-<?= escape($key) ?>"><?= escape($group['name']) ?> minimum · USD</label><input type="text" inputmode="decimal" name="minimums[<?= escape($key) ?>]" id="minimum-<?= escape($key) ?>" placeholder="Minimum $ · auto" maxlength="16" value="<?= escape($minimum) ?>"></div>
            </div><?php endforeach; ?>
        </details>
